using System;
using System.IO;
using System.Linq;
using System.Drawing;
using System.Diagnostics;
using System.Reflection;
using System.Threading;
using System.Windows.Forms;
using SplifyWin;
class BasicRenderingCheck {
 static BindingFlags flags=BindingFlags.NonPublic|BindingFlags.Instance;static int checks;
 static void Check(bool value,string text){if(!value)throw new Exception(text);checks++;Console.WriteLine("PASS "+text);}
 static void Page(MainForm form,string page){typeof(MainForm).GetMethod("ShowPage",flags).Invoke(form,new object[]{page});Application.DoEvents();}
 static void Wait(MainForm form,string name){var watch=Stopwatch.StartNew();while(form.Controls.Find(name,true).Length==0&&watch.ElapsedMilliseconds<15000){Application.DoEvents();Thread.Sleep(10);}Check(form.Controls.Find(name,true).Length>0,"loaded "+name);}
 static Bitmap Capture(Control control){var image=new Bitmap(control.Width,control.Height);control.DrawToBitmap(image,control.ClientRectangle);return image;}
 static void CheckWallpaper(string root){using(var tile=NetworkWallpaper.CopyTile()){int visible=0,max=0;for(int y=0;y<tile.Height;y++)for(int x=0;x<tile.Width;x++){int alpha=tile.GetPixel(x,y).A;if(alpha>0)visible++;max=Math.Max(max,alpha);}Check(visible>1000&&visible<tile.Width*tile.Height/4,"wallpaper uses small sparse line elements");Check(max<=30,"wallpaper remains low contrast");using(var image=new Bitmap(840,600))using(var graphics=Graphics.FromImage(image)){graphics.Clear(Color.FromArgb(12,17,31));NetworkWallpaper.Draw(graphics,new Rectangle(0,0,840,600));Check(image.GetPixel(35,16)==image.GetPixel(455,316),"wallpaper tile repeats without full-window allocation");image.Save(Path.Combine(root,"wallpaper.png"));}}}
 [STAThread]static int Main(string[] args){try{string root=Path.GetFullPath(args[0]);Directory.CreateDirectory(root);CheckWallpaper(root);Environment.SetEnvironmentVariable("MCRF_DATA_DIR",root);Environment.SetEnvironmentVariable("SPLIFY_WIN_DATA_DIR",root);Environment.SetEnvironmentVariable("MCRF_TEST_NO_STARTUP_SETUP","1");Environment.SetEnvironmentVariable("MCRF_TEST_NO_STARTUP_UPDATES","1");SynchronizationContext.SetSynchronizationContext(new WindowsFormsSynchronizationContext());using(var form=new MainForm(false,false)){form.Show();Application.DoEvents();var dashboard=(BlueGlassDashboard)typeof(MainForm).GetField("blueDashboard",flags).GetValue(form);var state=(ClientState)typeof(MainForm).GetField("state",flags).GetValue(form);state.AdvancedMode=false;UiTheme.Simple=false;Page(form,"");dashboard.BeginBasicResize();var watch=Stopwatch.StartNew();for(int i=0;i<20;i++){form.Size=new Size(1080+i*12,700+i*4);Application.DoEvents();using(var frame=Capture(dashboard))Check(frame.Width==dashboard.Width,"resize presents complete frame "+i);}watch.Stop();Console.WriteLine("BASIC RESIZE 20 frames "+watch.ElapsedMilliseconds+" ms");dashboard.EndBasicResize();Application.DoEvents();using(var frame=Capture(dashboard))frame.Save(Path.Combine(root,"basic-final.png"));Check(!(bool)typeof(BlueGlassDashboard).GetField("basicResizing",flags).GetValue(dashboard),"resize exits frozen-frame mode");watch.Restart();for(int i=0;i<4;i++){typeof(MainForm).GetMethod("ToggleWindowMaximize",flags).Invoke(form,null);Application.DoEvents();}Console.WriteLine("BASIC MAX/RESTORE x4 "+watch.ElapsedMilliseconds+" ms");Page(form,"servers");Application.DoEvents();Check(!Application.OpenForms.Cast<Form>().Any(f=>f.GetType().Name=="GlassMotionLayer"),"basic popup has no screen-sized animation window");Page(form,"");Check(!Application.OpenForms.Cast<Form>().Any(f=>f.GetType().Name=="GlassMotionLayer"),"closing popup leaves no animation window");state.AdvancedMode=true;UiTheme.Simple=true;Page(form,"zapret");Wait(form,"zapretHotkey_"+state.ZapretProfiles[0].Id);var hotkey=form.Controls.Find("zapretHotkey_"+state.ZapretProfiles[0].Id,true).First();using(var image=Capture(hotkey)){image.Save(Path.Combine(root,"hotkey.png"));var fill=image.GetPixel(image.Width/2,6);Check(fill.R<90&&fill.G<105&&fill.B<150,"hotkey retains dark palette, not grey/white");}Check(!hotkey.Region.IsVisible(0,0),"hotkey corners remain rounded");Page(form,"strategy-editor");Wait(form,"strategyParameterScroll");var left=form.Controls.Find("strategyParameterScroll",true).Single();var right=form.Controls.Find("strategyBlockPreviewSurface",true).Single();Check(left.Right<right.Left,"editor controls and block preview are side by side");using(var image=Capture((Control)typeof(MainForm).GetField("popupOverlay",flags).GetValue(form)))image.Save(Path.Combine(root,"editor-columns.png"));Page(form,"strategy-workshop");Wait(form,"customStrategyBudget");Check(new[]{"Что проверять","Для какого профиля","Название новых стратегий","Глубина поиска"}.All(t=>form.Controls.Cast<Control>().SelectMany(Descendants).OfType<Label>().Any(l=>l.Text==t)),"generator dropdowns have explicit labels");form.Close();}Console.WriteLine("OK "+checks+" checks");return 0;}catch(Exception ex){Console.WriteLine(ex);return 1;}}
 static System.Collections.Generic.IEnumerable<Control> Descendants(Control root){yield return root;foreach(Control child in root.Controls)foreach(var descendant in Descendants(child))yield return descendant;}
}
